css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .7); position: relative; }
.loader::before, .loader::after { content: ''; position: absolute; bottom: 0; width: 6%; height: 78%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #000 24%, var(--accent-2)), var(--accent-2)); }
.loader::before { left: 4%; }
.loader::after { right: 4%; }
.loader .net { position: absolute; top: 24%; left: 10%; width: 80%; height: 34%; border-top: calc(var(--loader-size) * .022) solid var(--accent); border-radius: 0 0 50% 50% / 0 0 100% 100%; transform-origin: top center; background: repeating-linear-gradient(90deg, var(--accent) 0 5%, transparent 5% 11%); animation: hammock calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
@keyframes hammock { 0%, 100% { transform: rotate(-7deg); } 50% { transform: rotate(7deg); } }
